import fs from 'node:fs/promises';
import path from 'node:path';

const KEY = /^[a-z][a-z0-9_-]*$/;

function fail(code, message) {
  return Object.assign(new Error(message), { code });
}

function invalid() {
  return fail('ERR_INVALID_BATCH', 'Invalid batch');
}

function corrupt(file) {
  return fail('ERR_LEDGER_CORRUPT', `Corrupt ledger file: ${file}`);
}

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

// Returns a normalized copy of the batch, or null if its shape is invalid.
function normalize(batch) {
  if (!isRecord(batch) || typeof batch.id !== 'string' || !batch.id || !Array.isArray(batch.entries)) return null;
  const entries = [];
  for (let i = 0; i < batch.entries.length; i++) {
    const entry = batch.entries[i];
    if (!isRecord(entry) || typeof entry.key !== 'string' || !KEY.test(entry.key) || !Number.isSafeInteger(entry.delta)) return null;
    // `+ 0` folds -0 into 0 so the in-memory snapshot matches its JSON round trip.
    entries.push({ key: entry.key, delta: entry.delta + 0 });
  }
  return { id: batch.id, entries };
}

function validate(batch) {
  const normalized = normalize(batch);
  if (!normalized) throw invalid();
  return normalized;
}

function sameEntries(a, b) {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (a[i].key !== b[i].key || a[i].delta !== b[i].delta) return false;
  }
  return true;
}

function initial() {
  return { revision: 0, balances: {}, receipts: [] };
}

function checkSnapshot(value, file) {
  if (!isRecord(value) || !isRecord(value.balances) || !Array.isArray(value.receipts)) throw corrupt(file);
  if (!Number.isSafeInteger(value.revision) || value.revision !== value.receipts.length) throw corrupt(file);
  for (const [key, balance] of Object.entries(value.balances)) {
    if (!KEY.test(key) || !Number.isSafeInteger(balance)) throw corrupt(file);
  }
  const receipts = value.receipts.map(receipt => normalize(receipt));
  if (receipts.includes(null)) throw corrupt(file);
  return { revision: value.revision, balances: { ...value.balances }, receipts };
}

async function readJson(io, file) {
  let text;
  try { text = await io.readFile(file, 'utf8'); }
  catch (error) { if (error && error.code === 'ENOENT') return undefined; throw error; }
  try { return JSON.parse(text); }
  catch { throw corrupt(file); }
}

// Writes the staging file, then atomically replaces the durable file.
async function save(io, directory, name, value) {
  const staging = path.join(directory, `${name}.tmp`);
  await io.writeFile(staging, JSON.stringify(value));
  await io.rename(staging, path.join(directory, `${name}.json`));
}

async function removePending(io, directory) {
  try { await io.unlink(path.join(directory, 'pending.json')); }
  catch (error) { if (!error || error.code !== 'ENOENT') throw error; }
}

// Returns the snapshot after applying the batch, or null if a balance leaves the safe range.
function apply(state, batch) {
  const balances = { ...state.balances };
  for (const { key, delta } of batch.entries) {
    const value = (Object.hasOwn(balances, key) ? balances[key] : 0) + delta;
    if (!Number.isSafeInteger(value)) return null;
    balances[key] = value;
  }
  return { revision: state.revision + 1, balances, receipts: [...state.receipts, batch] };
}

function findReceipt(state, id) {
  return state.receipts.find(receipt => receipt.id === id);
}

// Reads durable state without modifying it. `state` is the committed view including any
// pending transaction; `publish` says whether that view still has to be written to ledger.json.
async function load(io, directory) {
  await io.mkdir(directory, { recursive: true });
  const ledgerFile = path.join(directory, 'ledger.json');
  const pendingFile = path.join(directory, 'pending.json');
  const stored = await readJson(io, ledgerFile);
  let state = stored === undefined ? initial() : checkSnapshot(stored, ledgerFile);
  const rawPending = await readJson(io, pendingFile);
  if (rawPending === undefined) return { state, pending: false, publish: false };
  const pending = normalize(rawPending);
  if (!pending) throw corrupt(pendingFile);
  const receipt = findReceipt(state, pending.id);
  if (receipt) {
    // Already published; only the recovery metadata is left behind.
    if (!sameEntries(receipt.entries, pending.entries)) throw corrupt(pendingFile);
    return { state, pending: true, publish: false };
  }
  state = apply(state, pending);
  if (!state) throw corrupt(pendingFile);
  return { state, pending: true, publish: true };
}

async function finish(io, directory, loaded) {
  if (loaded.publish) await save(io, directory, 'ledger', loaded.state);
  if (loaded.pending) await removePending(io, directory);
}

export async function recoverLedger(directory, { io = fs } = {}) {
  const loaded = await load(io, directory);
  await finish(io, directory, loaded);
  return loaded.state;
}

export async function commitBatch(directory, batch, { io = fs, checkpoint } = {}) {
  batch = validate(batch);
  const loaded = await load(io, directory);
  const { state } = loaded;
  const receipt = findReceipt(state, batch.id);
  if (receipt && !sameEntries(receipt.entries, batch.entries)) {
    throw fail('ERR_BATCH_CONFLICT', 'Batch ID already used with different entries');
  }
  const next = receipt ? state : apply(state, batch);
  // Reject overflowing batches before any durable change, including recovery.
  if (!next) throw invalid();
  await finish(io, directory, loaded);
  if (receipt) return state;

  // The pending batch plus the published ledger fully determine the outcome:
  // recovery applies it unless its receipt is already in ledger.json.
  await save(io, directory, 'pending', batch);
  if (checkpoint) await checkpoint('prepared');
  // Balances and receipt are published together in a single atomic rename.
  await save(io, directory, 'ledger', next);
  if (checkpoint) await checkpoint('published');
  await removePending(io, directory);
  if (checkpoint) await checkpoint('complete');
  return next;
}

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import assert from 'node:assert/strict';
import { commitBatch, recoverLedger } from './src/ledger.js';

const a = { id: 'a', entries: [{ key: 'cash', delta: 5 }, { key: 'cash', delta: -2 }] };
const b = { id: 'b', entries: [{ key: 'cash', delta: 10 }, { key: 'bank', delta: 1 }] };
const c = { id: 'c', entries: [] };
const expected = { revision: 3, balances: { cash: 13, bank: 1 }, receipts: [a, b, c] };

function faulty(failAt, mode) {
  let n = 0;
  const wrap = name => async (...args) => {
    if (n++ === failAt) {
      if (name === 'writeFile' && mode === 'partial') await fs.writeFile(args[0], String(args[1]).slice(0, 7));
      throw Object.assign(new Error(`injected ${name}`), { code: 'EIO' });
    }
    return fs[name](...args);
  };
  return Object.fromEntries(['mkdir', 'readFile', 'writeFile', 'rename', 'unlink'].map(k => [k, wrap(k)]));
}

let cases = 0;
for (const target of [a, b, c]) {
  for (const mode of ['before', 'partial', 'checkpoint']) {
    for (let failAt = 0; failAt < 12; failAt++) {
      const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'sweep-'));
      for (const x of [a, b, c]) {
        if (x === target) break;
        await commitBatch(dir, x);
      }
      const phases = [];
      const io = mode === 'checkpoint' ? fs : faulty(failAt, mode);
      const checkpoint = async p => { phases.push(p); if (mode === 'checkpoint' && phases.length - 1 === failAt) throw new Error('stop'); };
      try { await commitBatch(dir, target, { io, checkpoint }); } catch {}
      // Fresh invocation: either recover first, or directly retry.
      if (failAt % 2) await recoverLedger(dir);
      for (const x of [a, b, c]) await commitBatch(dir, x);
      assert.deepEqual(await recoverLedger(dir), expected);
      assert.deepEqual(await commitBatch(dir, a), expected);
      await assert.rejects(commitBatch(dir, { id: 'a', entries: [] }), { code: 'ERR_BATCH_CONFLICT' });
      const files = (await fs.readdir(dir)).sort();
      assert.ok(!files.includes('pending.json'), files.join());
      await fs.rm(dir, { recursive: true });
      cases++;
    }
  }
}

// Phase order for a new batch, none for duplicate.
{
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'sweep-'));
  const phases = [];
  await commitBatch(dir, a, { checkpoint: async p => phases.push(p) });
  assert.deepEqual(phases, ['prepared', 'published', 'complete']);
  await commitBatch(dir, a, { checkpoint: async p => phases.push(p) });
  assert.equal(phases.length, 3);
  // Overflow / invalid batches leave durable data untouched, even with pending recovery outstanding.
  await commitBatch(dir, { id: 'big', entries: [{ key: 'x', delta: Number.MAX_SAFE_INTEGER }] });
  await assert.rejects(commitBatch(dir, b, { checkpoint: async p => { if (p === 'prepared') throw new Error('x'); } }));
  const before = [await fs.readFile(path.join(dir, 'ledger.json'), 'utf8'), await fs.readFile(path.join(dir, 'pending.json'), 'utf8')];
  await assert.rejects(commitBatch(dir, { id: 'o', entries: [{ key: 'x', delta: 1 }] }), { code: 'ERR_INVALID_BATCH' });
  for (const bad of [null, { id: '', entries: [] }, { id: 'q', entries: [{ key: 'Bad', delta: 1 }] }, { id: 'q', entries: [{ key: 'k', delta: 1.5 }] }]) {
    await assert.rejects(commitBatch(dir, bad), { code: 'ERR_INVALID_BATCH' });
  }
  const after = [await fs.readFile(path.join(dir, 'ledger.json'), 'utf8'), await fs.readFile(path.join(dir, 'pending.json'), 'utf8')];
  assert.deepEqual(after, before);
  const s = await recoverLedger(dir);
  assert.equal(s.revision, 3);
  assert.equal(s.balances.cash, 13);
  // Invalid JSON rejects without reset.
  await fs.writeFile(path.join(dir, 'ledger.json'), '{oops');
  await assert.rejects(recoverLedger(dir));
  await assert.rejects(commitBatch(dir, c));
  assert.equal(await fs.readFile(path.join(dir, 'ledger.json'), 'utf8'), '{oops');
  await fs.rm(dir, { recursive: true });
}
console.log('ok', cases);
